node -e "
const y=require('js-yaml'); const fs=require('fs');
const d=y.load(fs.readFileSync('.github/workflows/deploy-test.yml','utf8'));
console.log('✅ valid YAML');
const j=d.jobs;
console.log('deploy-test.outputs.sha :', j['deploy-test'].outputs.sha);
console.log('bundle-size checkout ref:', j['bundle-size'].steps[0].with.ref);
console.log('bundle-size needs       :', JSON.stringify(j['bundle-size'].needs));
console.log('test-gate needs         :', JSON.stringify(j['test-gate'].needs));
// sanity: resolve-sha step exists in deploy-test
const hasResolve = j['deploy-test'].steps.some(s=>s.id==='resolve-sha');
console.log('resolve-sha step present:', hasResolve);
"

