#!/usr/bin/env node
/**
 * Sync .cursor/rules/, .github/copilot-instructions.md, and .vscode/instructions/
 * from .claude/ + AGENTS.md sources.
 *
 * .claude/ + AGENTS.md is the master — never edit derived files that have a
 * synced-from header directly.
 *
 * Usage:
 *   node scripts/syncCursorRules.mjs          # report drift
 *   node scripts/syncCursorRules.mjs --check  # exit 1 if any drift found (CI mode)
 *   node scripts/syncCursorRules.mjs --fix    # regenerate auto-generated rules
 */

import fs from 'fs'
import path from 'path'
import {fileURLToPath} from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const ROOT = path.resolve(__dirname, '..')

const SQUAD_A_GLOBS = [
    'overrides/app/pages/cart/**',
    'overrides/app/pages/checkout/**',
    'overrides/app/pages/checkout-one-click/**',
    'overrides/app/pages/confirmation/**',
    'overrides/app/components/sf-payments-express/**',
    'overrides/app/components/sf-payments-express-buttons/**',
    'overrides/app/components/multiship/**',
    'overrides/app/components/bonus-product-view-modal/**'
].join(',')

const SQUAD_B_GLOBS = [
    'overrides/app/pages/home/**',
    'overrides/app/pages/product-detail/**',
    'overrides/app/pages/product-list/**',
    'overrides/app/pages/search/**',
    'overrides/app/pages/account/**',
    'overrides/app/pages/store-locator/**',
    'overrides/app/components/search/**',
    'overrides/app/components/store-locator/**'
].join(',')

/**
 * MANIFEST — defines the sync relationship between .claude/ sources and derived targets.
 *
 * All entries are `type: 'auto'` — `--fix` regenerates every target. Three generation modes:
 *
 *   mode: 'rule'    — single .claude/rules/ source → .cursor/rules/*.mdc with
 *                     Cursor frontmatter (description/globs/alwaysApply) injected.
 *
 *   mode: 'skill'   — single .claude/skills/<name>/SKILL.md source → .cursor/rules/skills/*.mdc.
 *                     The Cursor `description` is extracted from the source SKILL.md
 *                     frontmatter; `globs` and `alwaysApply` come from the manifest.
 *
 *   mode: 'compile' — one or more source files concatenated into one target
 *                     (.github/copilot-instructions.md, .vscode/instructions/*.md).
 *                     No Cursor frontmatter; each source body is preceded by a
 *                     `<!-- from: <source> -->` comment.
 */
const MANIFEST = [
    // Rule entries — 1:1 translations from .claude/rules/
    {
        source: '.claude/rules/frozenFiles.md',
        target: '.cursor/rules/tier1FrozenFiles.mdc',
        type: 'auto',
        mode: 'rule',
        frontmatter: {
            description: 'Tier 1 frozen files — must not be modified without explicit owner approval',
            globs: '',
            alwaysApply: true
        }
    },
    {
        source: '.claude/rules/protectedFiles.md',
        target: '.cursor/rules/tier2ProtectedFiles.mdc',
        type: 'auto',
        mode: 'rule',
        frontmatter: {
            description: 'Tier 2 protected files — feature branch only, requires second-developer PR review before merging',
            globs: '',
            alwaysApply: true
        }
    },
    {
        source: '.claude/rules/conventions.md',
        target: '.cursor/rules/conventions.mdc',
        type: 'auto',
        mode: 'rule',
        frontmatter: {
            description: 'Day-to-day code-writing conventions for every file in a PR',
            globs: '',
            alwaysApply: true
        }
    },
    {
        source: '.claude/rules/squadA.md',
        target: '.cursor/rules/squadA.mdc',
        type: 'auto',
        mode: 'rule',
        frontmatter: {
            description: 'Squad A territory — commerce and checkout. Load when working on cart, checkout, payments, or order files.',
            globs: SQUAD_A_GLOBS,
            alwaysApply: false
        }
    },
    {
        source: '.claude/rules/squadB.md',
        target: '.cursor/rules/squadB.mdc',
        type: 'auto',
        mode: 'rule',
        frontmatter: {
            description: 'Squad B territory — discovery and account. Load when working on PDP, PLP, search, account, or store locator files.',
            globs: SQUAD_B_GLOBS,
            alwaysApply: false
        }
    },
    {
        source: '.claude/rules/testing.md',
        target: '.cursor/rules/testing.mdc',
        type: 'auto',
        mode: 'rule',
        frontmatter: {
            description: 'Testing conventions — Vitest (unit), Storybook play (interaction), Playwright (E2E). Three layers, no overlap.',
            globs: '**/*.test.{ts,tsx},**/*.stories.tsx,e2e/**/*',
            alwaysApply: false
        }
