/**
 * Build valid YAML frontmatter string from a frontmatter object.
 */
function buildFrontmatter(fm) {
    const lines = ['---']
    lines.push(`description: ${fm.description}`)
    if (fm.globs) {
        lines.push(`globs: ${fm.globs}`)
    } else {
        lines.push(`globs:`)
    }
    lines.push(`alwaysApply: ${fm.alwaysApply}`)
    lines.push('---')
    return lines.join('\n')
}

/**
 * Strip existing frontmatter (content between the first pair of --- lines) from a markdown string.
 * Returns the body content without frontmatter.
 */
function stripFrontmatter(content) {
    const lines = content.split('\n')
    if (lines[0].trim() !== '---') {
        return content
    }
    const closingIndex = lines.findIndex((line, i) => i > 0 && line.trim() === '---')
    if (closingIndex === -1) {
        return content
    }
    return lines.slice(closingIndex + 1).join('\n').trimStart()
}

/**
 * Extract a single field value from a markdown file's YAML frontmatter.
 * Returns null if no frontmatter exists or the field is not present.
 */
function extractFrontmatterField(content, field) {
    const lines = content.split('\n')
    if (lines[0].trim() !== '---') return null
    const closingIndex = lines.findIndex((line, i) => i > 0 && line.trim() === '---')
    if (closingIndex === -1) return null
    const fmLines = lines.slice(1, closingIndex)
    const match = fmLines
        .map((line) => line.match(new RegExp(`^${field}:\\s*(.*)$`)))
        .find((m) => m !== null)
    return match ? match[1].trim() : null
}

/**
 * Get the mtime (modification time) of a file in milliseconds.
 * Returns 0 if the file does not exist.
 */
function getMtime(filePath) {
    try {
        return fs.statSync(filePath).mtimeMs
    } catch {
        return 0
    }
}

/**
 * Format a time difference in human-readable form.
 */
function formatTimeDiff(ms) {
    const seconds = Math.round(ms / 1000)
    const minutes = Math.round(seconds / 60)
    const hours = Math.round(minutes / 60)
    const days = Math.round(hours / 24)
    if (days > 0) return `${days} day${days === 1 ? '' : 's'} newer`
    if (hours > 0) return `${hours} hour${hours === 1 ? '' : 's'} newer`
    if (minutes > 0) return `${minutes} minute${minutes === 1 ? '' : 's'} newer`
    return `${seconds} second${seconds === 1 ? '' : 's'} newer`
}

function main() {
    const args = process.argv.slice(2)
    const isCheck = args.includes('--check')
    const isFix = args.includes('--fix')

    const results = {
        upToDate: [],
        driftDetected: [],
        targetMissing: [],
        sourceMissing: []
    }

    for (const entry of MANIFEST) {
        const sources = Array.isArray(entry.source) ? entry.source : [entry.source]
        const targetPath = path.join(ROOT, entry.target)

        // Check all sources exist
        const missingSources = sources.filter((s) => !fs.existsSync(path.join(ROOT, s)))
        if (missingSources.length > 0) {
            results.sourceMissing.push({entry, reason: `source file(s) not found: ${missingSources.join(', ')}`})
            continue
        }

        // Check target exists
        if (!fs.existsSync(targetPath)) {
            results.targetMissing.push({entry, reason: 'target file does not exist yet'})
            if (isFix) {
                regenerateTarget(entry)
                console.log(`  Created: ${entry.target}`)
            }
            continue
        }

        // For array sources: use the mtime of the newest source file as the comparison point
        const sourceMtime = Math.max(...sources.map((s) => getMtime(path.join(ROOT, s))))
        const targetMtime = getMtime(targetPath)

        if (sourceMtime > targetMtime) {
            const diff = sourceMtime - targetMtime
            results.driftDetected.push({entry, diff})
            if (isFix) {
                regenerateTarget(entry)
                console.log(`  Regenerated: ${entry.target}`)
            }
        } else {
            results.upToDate.push(entry)
        }
    }

    // Classify entries by mode for grouped reporting
    const ruleEntries = MANIFEST.filter((e) => e.mode === 'rule')
    const skillEntries = MANIFEST.filter((e) => e.mode === 'skill')
    const compileEntries = MANIFEST.filter((e) => e.mode === 'compile')

    const statusIcon = (entry) => {
        const inDrift = results.driftDetected.some((r) => r.entry.target === entry.target)
        const inMissing = results.targetMissing.some((r) => r.entry.target === entry.target)
        const inSourceMissing = results.sourceMissing.some((r) => r.entry.target === entry.target)
        if (inSourceMissing) return '❓'
        if (inMissing) return '❗'
        if (inDrift) return '⚠️ '
        return '✅'
    }

    const printSection = (label, entries) => {
        console.log(`\n${label} (${entries.length}):`)
        for (const entry of entries) {
            const driftEntry = results.driftDetected.find((r) => r.entry.target === entry.target)
            const suffix = driftEntry ? ` (source is ${formatTimeDiff(driftEntry.diff)})` : ''
            console.log(`  ${statusIcon(entry)} ${entry.target}${suffix}`)
        }
    }

    console.log('\nCursor Rules Sync Report')
    console.log('========================')
    printSection('Rules (.cursor/rules/*.mdc)', ruleEntries)
    printSection('Skills (.cursor/rules/skills/*.mdc)', skillEntries)
    printSection('Copilot / VS Code (compiled)', compileEntries)

    const totalDrift = results.driftDetected.length
    const totalMissing = results.targetMissing.length
    const totalSourceMissing = results.sourceMissing.length

    console.log('')
    if (totalDrift === 0 && totalMissing === 0 && totalSourceMissing === 0) {
        console.log('All targets are in sync with their .claude/ sources.')
    } else {
        if (totalMissing > 0) {
            console.log(`❗ Target missing: ${totalMissing} file(s)`)
            for (const {entry} of results.targetMissing) {
                console.log(`  - ${entry.target}`)
            }
        }
        if (totalSourceMissing > 0) {
            console.log(`❓ Source missing: ${totalSourceMissing} file(s)`)
            for (const {entry, reason} of results.sourceMissing) {
                console.log(`  - ${entry.target}: ${reason} (check MANIFEST)`)
            }
        }
        if (!isFix && (totalDrift > 0 || totalMissing > 0)) {
            console.log('\nRun with --fix to regenerate.')
        }
    }

    // Exit with code 1 in --check mode if any drift or missing targets
    if (isCheck) {
        const hasDrift =
            results.driftDetected.length > 0 ||
            results.targetMissing.length > 0 ||
            results.sourceMissing.length > 0
        if (hasDrift) {
            process.exit(1)
        }
    }
}

/**
 * Regenerate a target file from its source(s). Dispatches on entry.mode:
 *   - 'rule':    single source, full Cursor frontmatter from manifest
 *   - 'skill':   single source, description extracted from source frontmatter
 *   - 'compile': multi-source concatenation, plain markdown (no Cursor frontmatter)
 */
function regenerateTarget(entry) {
    const sources = Array.isArray(entry.source) ? entry.source : [entry.source]
    const targetPath = path.join(ROOT, entry.target)
    const syncList = sources.join(', ')
    const syncedFromComment = `<!-- synced-from: ${syncList} — edit the source(s), not this file, then run: node scripts/syncCursorRules.mjs --fix -->`

    let output

    if (entry.mode === 'rule') {
        const body = stripFrontmatter(fs.readFileSync(path.join(ROOT, sources[0]), 'utf8'))
        const frontmatter = buildFrontmatter(entry.frontmatter)
        output = `${frontmatter}\n${syncedFromComment}\n\n${body}`
    } else if (entry.mode === 'skill') {
        const sourceContent = fs.readFileSync(path.join(ROOT, sources[0]), 'utf8')
        const description = extractFrontmatterField(sourceContent, 'description')
        if (!description) {
            throw new Error(`Skill source ${sources[0]} is missing a 'description' field in its frontmatter`)
        }
        const body = stripFrontmatter(sourceContent)
        const frontmatter = buildFrontmatter({
            description,
            globs: entry.frontmatter?.globs ?? '',
            alwaysApply: entry.frontmatter?.alwaysApply ?? false
        })
        output = `${frontmatter}\n${syncedFromComment}\n\n${body}`
    } else if (entry.mode === 'compile') {
        const parts = sources.map((s) => {
            const body = stripFrontmatter(fs.readFileSync(path.join(ROOT, s), 'utf8')).trim()
            return `<!-- from: ${s} -->\n\n${body}`
        })
        const title = entry.title ? `# ${entry.title}\n\n` : ''
        output = `${syncedFromComment}\n\n${title}${parts.join('\n\n---\n\n')}\n`
    } else {
        throw new Error(`Unknown mode '${entry.mode}' for target ${entry.target}`)
    }

    const targetDir = path.dirname(targetPath)
    if (!fs.existsSync(targetDir)) {
        fs.mkdirSync(targetDir, {recursive: true})
    }
    fs.writeFileSync(targetPath, output, 'utf8')
}

main()

/**
 * versionGuard.mjs — downgrade protection for tag-based environment promotion.
 *
 * On the GitHub Team plan, a deploy's auto-created Deployment records the *trigger*
 * ref (the default branch), NOT the tag that was actually deployed. So we record the
 * deployed tag ourselves (an explicit GitHub Deployment) and read it back here to
 * block accidental downgrades on the manually-promoted tiers (test/uat/staging/prod).
 *
 * Usage (from a deploy-*.yml, after `npm install`, with GH_TOKEN set):
 *   node scripts/versionGuard.mjs check  <env> <ref>   # before push — block a downgrade
 *   node scripts/versionGuard.mjs record <env> <ref>   # after a successful push — record the tag
 *
 * <env> is the GitHub Environment name (test | uat | staging | prod).
 *
 * `check` behaviour:
 *   - <ref> is not a version tag       -> skip/allow (e.g. deploying a feature branch to Test)
 *   - <ref> not valid semver           -> fail closed (exit 1)
 *   - no prior tag on the env          -> allow (first deploy)
 *   - <ref> strictly older             -> BLOCK (exit 1)
 *   - <ref> equal or newer             -> allow
 *   - lookup error / invalid stored ref -> fail closed (exit 1)
 *
 * `record` skips non-version-tag refs; it FAILS the run if it cannot create the deployment record
 * (a missing baseline would let a later run downgrade), and only warns if the follow-up status
 * update fails (the ref is already recorded, which is what the guard reads).
 */
import {execFileSync} from 'node:child_process'
import semver from 'semver'

// vX.Y.Z with an optional -rc.N or -hotfix.N suffix (matches the repo tag rulesets).
const VERSION_TAG = /^v\d+\.\d+\.\d+(-rc\.\d+|-hotfix\.\d+)?$/

const [mode, env, ref] = process.argv.slice(2)
const repo = process.env.GITHUB_REPOSITORY

const die = (msg) => {
    console.error(`✗ version-guard: ${msg}`)
    process.exit(1)
}
const pass = (msg) => {
    console.log(`✓ version-guard: ${msg}`)
    process.exit(0)
}

if (!['check', 'record'].includes(mode) || !env || !ref) {
    die('usage: versionGuard.mjs <check|record> <env> <ref>')
}
if (!repo) die('GITHUB_REPOSITORY is not set')

/** Run `gh` and return stdout. Optional `input` is written to stdin. Throws on non-zero exit. */
function gh(args, input) {
    return execFileSync('gh', args, {encoding: 'utf8', input})
}

/**
 * Newest deployment ref for `env` that is a valid version tag, or null. Throws on API error.
 * Pages through deployments (newest-first) so a long run of non-version (branch) deploys can't bury
 * the last tag record. Skips non-version refs; fails closed if a version-shaped ref is not valid
 * semver (so a malformed baseline like `v01.2.3` can't crash the compare or slip a downgrade through).
 */
function currentDeployedTag() {
    const MAX_PAGES = 20 // 20 x 100 = 2000 deployments of headroom
    for (let page = 1; page <= MAX_PAGES; page++) {
        const out = gh([
            'api',
            `repos/${repo}/deployments?environment=${env}&per_page=100&page=${page}`,
            '--jq',
            '[.[].ref]'
        ])
        const refs = JSON.parse(out.trim() || '[]')
        if (refs.length === 0) break // no more pages
        for (const r of refs) {
            if (!VERSION_TAG.test(r)) continue // skip branches / develop / other non-version refs
            if (!semver.valid(r)) die(`stored deployment ref '${r}' for '${env}' is not valid semver — failing closed`)
            return r // newest valid version tag
        }
    }
    return null
}

const detail = (err) => String(err.stderr || err.message).trim().slice(0, 160)

if (mode === 'check') {
    if (!VERSION_TAG.test(ref)) pass(`'${ref}' is not a version tag — skipping downgrade check`)
    if (!semver.valid(ref)) die(`'${ref}' is not valid semver`)

    let current
    try {
        current = currentDeployedTag()
    } catch (err) {
        // Fail closed: if we cannot determine what is live, do not risk a downgrade.
        die(`could not read deployments for '${env}' (failing closed): ${detail(err)}`)
    }

    if (current === null) pass(`no prior version tag on '${env}' — first deploy, allowing ${ref}`)
    if (semver.lt(ref, current)) {
        die(`refusing downgrade on '${env}': ${ref} is older than the live ${current}`)
    }
    pass(`${ref} is not older than the live ${current} on '${env}' — allowed`)
}

if (mode === 'record') {
    if (!VERSION_TAG.test(ref)) pass(`'${ref}' is not a version tag — nothing to record`)
    if (!semver.valid(ref)) die(`'${ref}' is not valid semver — refusing to record it`)
    const body = JSON.stringify({
        ref,
        environment: env,
        auto_merge: false,
        required_contexts: [],
        description: `tag ${ref}`
    })
    let id
    try {
        id = gh(['api', `repos/${repo}/deployments`, '--input', '-', '--jq', '.id'], body).trim()
    } catch (err) {
        // A missing record lets a later run read an older tag and allow a downgrade — fail loudly.
        die(`could not record the deployed tag for '${env}' — the guard baseline is now stale: ${detail(err)}`)
    }
    try {
        gh([
            'api',
            `repos/${repo}/deployments/${id}/statuses`,
            '-f',
            'state=success',
            '-f',
            `description=deployed ${ref}`
        ])
    } catch (err) {
        // The ref is already recorded (that is what the guard reads); the status is cosmetic — warn only.
        console.error(`::warning::version-guard: recorded deployment ${id} but could not set its status (${detail(err)})`)
    }
    pass(`recorded deployment ${id} for '${env}' = ${ref}`)
}

